        {unsafeParcel&&<p role="status" className="mt-2 text-xs text-amber-800">{PARCEL_DEFINITION_MESSAGE}</p>}
        {!salesOnly&&product.unitsPerSalePackage > 1 && <div className="mt-4 hidden grid-cols-2 gap-2 sm:grid">
